function normalizeResearchApprovalLabel(value) {
  const text = safeResearchText(value || "");
  return /^(approved(?: manual review| for review)?|ceo b approved)$/i.test(text)
    ? RESEARCH_APPROVAL_LABEL
    : text;
}

function showNotification(message, type = "success") {
  console.log(`[Notification] ${message}`);
  let container = document.getElementById("toast-container");
  if (!container) {
    container = document.createElement("div");
    container.id = "toast-container";
    container.style.position = "fixed";
    container.style.top = "16px";
    container.style.right = "16px";
    container.style.left = "auto";
    container.style.bottom = "auto";
    container.style.zIndex = "99999";
    container.style.display = "flex";
    container.style.flexDirection = "column";
    container.style.gap = "8px";
    container.style.pointerEvents = "none";
    container.style.maxWidth = "min(360px, calc(100vw - 32px))";
    document.body.appendChild(container);
  }
  
  const toast = document.createElement("div");
  toast.style.pointerEvents = "auto";
  toast.style.padding = "10px 16px";
  toast.style.background = "#0e1012";
  toast.style.border = "1px solid var(--green, #42d9c8)";
  if (type === "error") {
    toast.style.border = "1px solid var(--red, #f75656)";
  } else if (type === "warning") {
    toast.style.border = "1px solid var(--amber, #ffbe4d)";
  }
  toast.style.borderRadius = "4px";
  toast.style.color = "#c0c4cc";
  toast.style.fontFamily = "monospace";
  toast.style.fontSize = "11px";
  toast.style.boxShadow = "0 4px 12px rgba(0,0,0,0.5)";
  toast.style.minWidth = "200px";
  toast.style.maxWidth = "100%";
  toast.style.opacity = "0";
  toast.style.transform = "translateY(-10px)";
  toast.style.transition = "all 0.3s cubic-bezier(0.16, 1, 0.3, 1)";
  
  const esc = (str) => String(str).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  
  toast.innerHTML = `<span style="color: ${type === 'error' ? 'var(--red, #f75656)' : type === 'warning' ? 'var(--amber, #ffbe4d)' : 'var(--green, #42d9c8)'}; font-weight: bold;">[${type.toUpperCase()}]</span> <span style="line-height: 1.3;">${esc(message)}</span>`;
  
  container.appendChild(toast);
  
  setTimeout(() => {
    toast.style.opacity = "1";
    toast.style.transform = "translateY(0)";
  }, 10);
  
  setTimeout(() => {
    toast.style.opacity = "0";
    toast.style.transform = "translateY(-10px)";
    setTimeout(() => {
      toast.remove();
      if (container.children.length === 0) {
        container.remove();
      }
    }, 300);
  }, 3500);
}
window.showNotification = showNotification;

function isStaticMode() {
  return window.location.hostname.includes("github.io") || window.location.protocol === "file:";
}

function initPickaxeStarlightField() {
  const canvas = document.querySelector("#pickaxe-starlight-field");
  if (!canvas || canvas.dataset.initialized === "true") return;
  const context = canvas.getContext?.("2d");
  if (!context) {
    canvas.hidden = true;
    return;
  }

  canvas.dataset.initialized = "true";
  canvas.dataset.version = "2";
  const reducedMotionQuery = window.matchMedia("(prefers-reduced-motion: reduce)");
  const palette = [
    { color: [241, 239, 232], weight: 12 },
    { color: [202, 216, 235], weight: 4 },
    { color: [216, 180, 90], weight: 1 },
    { color: [112, 190, 184], weight: 1 },
  ];
  const layers = [
    { share: 0.62, radius: [0.36, 0.72], alpha: [0.16, 0.34], drift: 0.0008 },
    { share: 0.31, radius: [0.58, 1.08], alpha: [0.24, 0.5], drift: 0.0017 },
    { share: 0.07, radius: [0.9, 1.5], alpha: [0.42, 0.68], drift: 0.003 },
  ];
  let width = 0;
  let height = 0;
  let pixelRatio = 1;
  let stars = [];
  let constellations = [];
  let shootingStar = null;
  let animationFrame = 0;
  let resizeFrame = 0;
  let lastPaintAt = 0;
  let nextShootingStarAt = Number.POSITIVE_INFINITY;

  function starCount() {
    if (window.innerWidth <= 760) {
      return Math.max(96, Math.min(150, Math.round((width * height) / 4000)));
    }
    return Math.max(190, Math.min(310, Math.round((width * height) / 4700)));
  }

  function randomBetween([minimum, maximum]) {
    return minimum + Math.random() * (maximum - minimum);
  }

  function pickColor() {
    const totalWeight = palette.reduce((total, entry) => total + entry.weight, 0);
    let choice = Math.random() * totalWeight;
    for (const entry of palette) {
      choice -= entry.weight;
      if (choice <= 0) return entry.color;
    }
    return palette[0].color;
  }

  function createStars() {
    const count = starCount();
    stars = Array.from({ length: count }, (_, index) => {
      const ratio = index / count;
      const layer = ratio < layers[0].share
        ? layers[0]
        : ratio < layers[0].share + layers[1].share
          ? layers[1]
          : layers[2];
      return {
        x: Math.random() * width,
        y: Math.random() * height,
        radius: randomBetween(layer.radius),
        alpha: randomBetween(layer.alpha),
        shimmer: 0.025 + Math.random() * 0.09,
        speed: 0.00012 + Math.random() * 0.00025,
        phase: Math.random() * Math.PI * 2,
        driftX: layer.drift * (0.72 + Math.random() * 0.56),
        driftY: layer.drift * (0.16 + Math.random() * 0.2),
        hero: index >= count - Math.max(3, Math.round(count * 0.018)),
        color: pickColor(),
      };
    });
    const constellationCount = Math.max(2, Math.min(5, Math.round(width / 360)));
    constellations = Array.from({ length: constellationCount }, () => {
      const start = Math.floor(Math.random() * stars.length);
      const neighbors = stars
        .map((star, index) => ({
          index,
          distance: index === start ? Number.POSITIVE_INFINITY : Math.hypot(star.x - stars[start].x, star.y - stars[start].y),
        }))
        .sort((left, right) => left.distance - right.distance)
        .slice(0, 2)
        .map((entry) => entry.index);
      return [start, ...neighbors];
    });
    canvas.dataset.starCount = String(stars.length);
  }

  function scheduleShootingStar(timestamp = performance.now()) {
    nextShootingStarAt = timestamp + 30000 + Math.random() * 30000;
  }

  function createShootingStar(timestamp) {
    const speed = 820 + Math.random() * 180;
    const angle = 0.38 + Math.random() * 0.12;
    shootingStar = {
      bornAt: timestamp,
      duration: 480 + Math.random() * 180,
      startX: -90 + Math.random() * width * 0.55,
      startY: 28 + Math.random() * height * 0.28,
      velocityX: Math.cos(angle) * speed,
      velocityY: Math.sin(angle) * speed,
      length: 100 + Math.random() * 54,
    };
  }

  function starPosition(star, timestamp, staticOnly) {
    if (staticOnly) return { x: star.x, y: star.y };
    return {
      x: (star.x + timestamp * star.driftX) % width,
      y: (star.y + timestamp * star.driftY) % height,
    };
  }

  function drawAtmosphere() {
    const goldGlow = context.createRadialGradient(width * 0.78, height * 0.12, 0, width * 0.78, height * 0.12, width * 0.42);
    goldGlow.addColorStop(0, "rgba(212, 175, 55, 0.055)");
    goldGlow.addColorStop(1, "rgba(212, 175, 55, 0)");
    context.fillStyle = goldGlow;
    context.fillRect(0, 0, width, height);

    const tealGlow = context.createRadialGradient(width * 0.18, height * 0.72, 0, width * 0.18, height * 0.72, width * 0.34);
    tealGlow.addColorStop(0, "rgba(72, 150, 151, 0.035)");
    tealGlow.addColorStop(1, "rgba(72, 150, 151, 0)");
    context.fillStyle = tealGlow;
    context.fillRect(0, 0, width, height);
  }

  function drawConstellations(timestamp, staticOnly) {
    context.lineWidth = 0.55;
    constellations.forEach((indices) => {
      const points = indices.map((index) => starPosition(stars[index], timestamp, staticOnly));
      const segmentsAreLocal = points.every((point, index) => {
        if (!index) return true;
        return Math.hypot(point.x - points[index - 1].x, point.y - points[index - 1].y) < Math.min(220, width * 0.22);
      });
      if (!segmentsAreLocal) return;
      context.beginPath();
      context.moveTo(points[0].x, points[0].y);
      points.slice(1).forEach((point) => context.lineTo(point.x, point.y));
      context.strokeStyle = "rgba(178, 197, 210, 0.045)";
      context.stroke();
    });
  }

  function drawStars(timestamp, staticOnly = false) {
    context.clearRect(0, 0, width, height);
    drawAtmosphere();
    drawConstellations(timestamp, staticOnly);
    stars.forEach((star) => {
      const twinkle = staticOnly ? 0 : Math.sin(timestamp * star.speed + star.phase) * star.shimmer;
      const alpha = Math.max(0.12, Math.min(star.hero ? 0.86 : 0.64, star.alpha + twinkle));
      const position = starPosition(star, timestamp, staticOnly);
      if (star.hero) {
        context.beginPath();
        context.fillStyle = `rgba(${star.color[0]}, ${star.color[1]}, ${star.color[2]}, ${alpha * 0.1})`;
        context.arc(position.x, position.y, star.radius * 4.2, 0, Math.PI * 2);
        context.fill();
      }
      context.beginPath();
      context.fillStyle = `rgba(${star.color[0]}, ${star.color[1]}, ${star.color[2]}, ${alpha})`;
      context.arc(position.x, position.y, star.radius, 0, Math.PI * 2);
      context.fill();
    });
  }

  function drawShootingStar(timestamp) {
    if (!shootingStar) return;
    const elapsed = timestamp - shootingStar.bornAt;
    if (elapsed >= shootingStar.duration) {
      shootingStar = null;
      scheduleShootingStar(timestamp);
      return;
    }

    const progress = elapsed / shootingStar.duration;
    const seconds = elapsed / 1000;
    const headX = shootingStar.startX + shootingStar.velocityX * seconds;
    const headY = shootingStar.startY + shootingStar.velocityY * seconds;
    const velocityLength = Math.hypot(shootingStar.velocityX, shootingStar.velocityY);
    const tailX = headX - (shootingStar.velocityX / velocityLength) * shootingStar.length;
    const tailY = headY - (shootingStar.velocityY / velocityLength) * shootingStar.length;
    const fade = Math.sin(Math.PI * progress) * 0.34;
    const gradient = context.createLinearGradient(tailX, tailY, headX, headY);
    gradient.addColorStop(0, "rgba(212, 175, 55, 0)");
    gradient.addColorStop(0.72, `rgba(226, 215, 190, ${fade * 0.42})`);
    gradient.addColorStop(1, `rgba(255, 248, 225, ${fade})`);
    context.beginPath();
    context.moveTo(tailX, tailY);
    context.lineTo(headX, headY);
    context.strokeStyle = gradient;
    context.lineWidth = 1;
    context.lineCap = "round";
    context.stroke();
  }

  function paint(timestamp) {
    animationFrame = 0;
    if (document.hidden || reducedMotionQuery.matches) return;
    if (timestamp - lastPaintAt < 32) {
      animationFrame = requestAnimationFrame(paint);
      return;
    }
    lastPaintAt = timestamp;
    drawStars(timestamp);
    if (!shootingStar && timestamp >= nextShootingStarAt) createShootingStar(timestamp);
    drawShootingStar(timestamp);
    animationFrame = requestAnimationFrame(paint);
  }

  function start() {
    if (animationFrame || document.hidden || reducedMotionQuery.matches) return;
    canvas.dataset.animation = "running";
    lastPaintAt = 0;
    animationFrame = requestAnimationFrame(paint);
  }

  function stop(nextState = "paused") {
    if (animationFrame) cancelAnimationFrame(animationFrame);
    animationFrame = 0;
    canvas.dataset.animation = nextState;
  }

  function configureMotion() {
    shootingStar = null;
    if (reducedMotionQuery.matches) {
      stop("static");
      nextShootingStarAt = Number.POSITIVE_INFINITY;
      drawStars(0, true);
      return;
    }
    scheduleShootingStar();
    start();
  }

  function resize() {
    width = Math.max(1, window.innerWidth);
    height = Math.max(1, window.innerHeight);
    pixelRatio = Math.min(window.devicePixelRatio || 1, 1.5);
    canvas.width = Math.round(width * pixelRatio);
    canvas.height = Math.round(height * pixelRatio);
    context.setTransform(pixelRatio, 0, 0, pixelRatio, 0, 0);
    createStars();
    drawStars(0, reducedMotionQuery.matches);
  }

  function queueResize() {
    if (resizeFrame) return;
    resizeFrame = requestAnimationFrame(() => {
      resizeFrame = 0;
      resize();
    });
  }

  document.addEventListener("visibilitychange", () => {
    if (document.hidden) {
      stop("paused");
      return;
    }
    if (reducedMotionQuery.matches) {
      drawStars(0, true);
      return;
    }
    scheduleShootingStar();
    start();
  });
  window.addEventListener("resize", queueResize, { passive: true });
  if (typeof reducedMotionQuery.addEventListener === "function") {
    reducedMotionQuery.addEventListener("change", configureMotion);
  } else {
    reducedMotionQuery.addListener(configureMotion);
  }

  resize();
  configureMotion();
}

