function renderFounderProfile() {
  const isPublic = state.founderMode === "public";
  const landing = ensureFounderLandingPage();
  Array.from(els.founderSection.children).forEach((child) => {
    child.hidden = isPublic && child !== landing;
  });
  landing.hidden = !isPublic;
  els.founderSection.classList.toggle("public-profile", isPublic);
  els.founderSection.classList.toggle("command-profile", !isPublic);
  els.founderSection.classList.toggle("landing-profile", isPublic);
  if (isPublic) {
    proofOfWorkIndex = 0;
    landing.innerHTML = renderFounderLandingPage();
    return;
  }
  els.founderThink.innerHTML = founderProfile.howYouThink.map(([title, detail], index) => renderFounderTrait(title, detail, founderIcon(index))).join("");
  els.founderStrengths.innerHTML = founderProfile.strengths.map(([title, detail], index) => renderFounderTrait(title, detail, strengthIcon(index))).join("");
  els.founderValues.innerHTML = founderProfile.values.map((item) => `<p><span>◇</span>${escapeHtml(item)}</p>`).join("");
  els.founderAction.innerHTML = founderProfile.inAction.map((item) => `<p><span>✓</span>${escapeHtml(item)}</p>`).join("");
  els.founderBlindSpots.innerHTML = founderProfile.blindSpots.map((item) => `<li>${escapeHtml(item)}</li>`).join("");
  els.founderEnvironment.innerHTML = founderProfile.idealEnvironment.map((item) => `<p><span>✦</span>${escapeHtml(item)}</p>`).join("");
  els.founderVibeBars.innerHTML = founderProfile.vibeCheck.map(([label, score]) => `
    <div class="vibe-row">
      <span>${escapeHtml(label)}</span>
      <div class="vibe-track"><i style="width:${score * 10}%"></i></div>
      <strong>${score}/10</strong>
    </div>
  `).join("");
  els.founderNorthStar.innerHTML = founderProfile.northStar.map((item) => `<span>${escapeHtml(item)}</span>`).join("");
}

function ensureFounderLandingPage() {
  let landing = els.founderSection.querySelector(".founder-landing-page");
  if (!landing) {
    landing = document.createElement("div");
    landing.className = "founder-landing-page";
    landing.hidden = true;
    els.founderSection.prepend(landing);
  }
  return landing;
}

function renderProofOfWorkCard(card, index) {
  if (!card) return "";
  return `
    <article class="proof-work-card" data-proof-card-index="${index}">
      <div class="proof-work-card-head">
        <span>${escapeHtml(card.category)}</span>
        <strong>${escapeHtml(card.status)}</strong>
      </div>
      <blockquote>${escapeHtml(card.proof)}</blockquote>
      <div class="proof-work-card-meta">
        <div>
          <small>${escapeHtml(card.attribution)}</small>
          <h3>${escapeHtml(card.title)}</h3>
        </div>
        <a href="${escapeHtml(card.route)}" aria-label="Open ${escapeHtml(card.title)} route">Open route</a>
      </div>
      <p class="proof-work-safety">${escapeHtml(card.safety)}</p>
    </article>
  `;
}

function renderProofOfWorkCards(startIndex = proofOfWorkIndex) {
  if (!proofOfWorkCards.length) return "";
  return [0, 1].map((offset) => {
    const index = (startIndex + offset + proofOfWorkCards.length) % proofOfWorkCards.length;
    return renderProofOfWorkCard(proofOfWorkCards[index], index);
  }).join("");
}

function proofOfWorkCountLabel(index = proofOfWorkIndex) {
  const current = String(index + 1).padStart(2, "0");
  const total = String(proofOfWorkCards.length).padStart(2, "0");
  return `${current} / ${total}`;
}

window.moveProofOfWorkCarousel = (direction) => {
  if (!proofOfWorkCards.length) return;
  proofOfWorkIndex = (proofOfWorkIndex + direction + proofOfWorkCards.length) % proofOfWorkCards.length;
  const cards = document.querySelector("#proofOfWorkCards");
  const count = document.querySelector("#proofOfWorkCount");
  if (cards) cards.innerHTML = renderProofOfWorkCards(proofOfWorkIndex);
  if (count) count.textContent = proofOfWorkCountLabel(proofOfWorkIndex);
};

