function portraitStyle(agent, size) {
  const scale = 0.68;
  const x = Math.round(size / 2 - (agent.portrait?.x || 760) * scale);
  const y = Math.round(size / 2 - (agent.portrait?.y || 285) * scale);
  return `--portrait-size:${size}px; --portrait-x:${x}px; --portrait-y:${y}px;`;
}

